/**
 * Barrel for the Zod contract. Client forms import the individual schema they
 * bind to a resolver; Server Actions import the same symbol. Never redeclare a
 * shape locally — extend the schema here instead.
 */
export * from "./common";
export * from "./slug";
export * from "./role";
export * from "./auth";
export * from "./session";
export * from "./organization";
export * from "./member";
export * from "./invitation";
export * from "./project";
export * from "./issue";
export * from "./comment";
export * from "./label";
export * from "./attachment";
export * from "./notification";
export * from "./activity";
export * from "./billing";
export * from "./feature-flag";
export * from "./search";
export * from "./webhook";
export * from "./export";
export * from "./pagination";
/** Barrel for the Taskflow shared type contract. Prefer importing from the
 *  specific module (`@/types/issue`) in app code; this barrel exists for the
 *  handful of places that genuinely need many domains at once. */
export * from "./common";
export * from "./member";
export * from "./organization";
export * from "./project";
export * from "./issue";
export * from "./comment";
export * from "./notification";
export * from "./billing";
export * from "./activity";
export * from "./feature-flag";
export * from "./permission";
export * from "./event";
export * from "./api";
import { z } from "zod";
import {
  archiveScopeSchema,
  hexColorSchema,
  isoTimestampSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";
import { projectKeySchema, slugSchema } from "./slug";

export const projectVisibilitySchema = z.enum(["private", "org", "public"]);
export const projectStatusSchema = z.enum(["active", "paused", "completed"]);

export const createProjectSchema = z.object({
  orgId: orgIdSchema,
  name: z.string().min(2).max(80),
  slug: slugSchema,
  key: projectKeySchema,
  description: z.string().max(2_000).nullable().default(null),
  visibility: projectVisibilitySchema.default("org"),
  leadId: userIdSchema.nullable().default(null),
  color: hexColorSchema.default("#6366f1"),
  targetDate: isoTimestampSchema.nullable().default(null),
});

export const updateProjectSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema,
  name: z.string().min(2).max(80).optional(),
  description: z.string().max(2_000).nullable().optional(),
  visibility: projectVisibilitySchema.optional(),
  status: projectStatusSchema.optional(),
  leadId: userIdSchema.nullable().optional(),
  color: hexColorSchema.optional(),
  targetDate: isoTimestampSchema.nullable().optional(),
});

export const archiveProjectSchema = z.object({
    name: row.name,
    color: row.color,
    description: row.description,
  };
}

export function toAttachment(row: AttachmentRow): IssueAttachment {
  return {
    id: brandId<AttachmentId>(row.id),
    orgId: brandId<OrgId>(row.orgId),
    issueId: brandId<IssueId>(row.issueId),
    filename: row.filename,
    contentType: row.contentType,
    sizeBytes: row.sizeBytes,
    uploadedBy: brandId<UserId>(row.uploadedBy),
    createdAt: brandStamp(row.createdAt),
    updatedAt: brandStamp(row.updatedAt),
  };
}

export function toComment(row: CommentRow): Comment {
  return {
    id: brandId<CommentId>(row.id),
    orgId: brandId<OrgId>(row.orgId),
    issueId: brandId<IssueId>(row.issueId),
    authorId: brandId<UserId>(row.authorId),
    body: row.body,
    parentId: row.parentId === null ? null : brandId<CommentId>(row.parentId),
    editedAt: row.editedAt,
    mentionedUserIds: parseJsonArray<UserId>(row.mentionedUserIds),
    createdAt: brandStamp(row.createdAt),
    updatedAt: brandStamp(row.updatedAt),
    archivedAt: brandStampOrNull(row.archivedAt),
  };
}

export function toNotification(row: NotificationRow): Notification {
  return {
    id: brandId<NotificationId>(row.id),
    orgId: brandId<OrgId>(row.orgId),
    recipientId: brandId<UserId>(row.recipientId),
    kind: row.kind,
    title: row.title,
    body: row.body,
    href: row.href,
    actorId: row.actorId === null ? null : brandId<UserId>(row.actorId),
    readAt: brandStampOrNull(row.readAt),
    channels: parseJsonArray<NotificationChannel>(row.channels),
    createdAt: brandStamp(row.createdAt),
    updatedAt: brandStamp(row.updatedAt),
  };
}

export function toPreference(
  row: NotificationPreferenceRow,
): NotificationPreference {
  return {
    orgId: brandId<OrgId>(row.orgId),
    userId: brandId<UserId>(row.userId),
    kind: row.kind,
    inApp: row.inApp,
    email: row.email,
    digestOnly: row.digestOnly,
  };
}

}

export function parseJsonObject(
  raw: string,
): Readonly<Record<string, string | number | boolean | null>> {
  try {
    const parsed: unknown = JSON.parse(raw);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      return parsed as Record<string, string | number | boolean | null>;
    }
    return {};
  } catch {
    return {};
  }
}

export function toUser(row: UserRow): User {
  return {
    id: brandId<UserId>(row.id),
    email: row.email,
    name: row.name,
    avatarUrl: row.avatarUrl,
    timezone: row.timezone,
    emailVerifiedAt: brandStampOrNull(row.emailVerifiedAt),
    createdAt: brandStamp(row.createdAt),
    updatedAt: brandStamp(row.updatedAt),
  };
}

export function toOrganization(row: OrganizationRow): Organization {
  return {
    id: brandId<OrgId>(row.id),
    name: row.name,
    slug: row.slug,
    ownerId: brandId<UserId>(row.ownerId),
    plan: row.plan,
    logoUrl: row.logoUrl,
    trialEndsAt: brandStampOrNull(row.trialEndsAt),
    settings: {
      defaultIssueStatus: row.defaultIssueStatus,
      allowPublicProjects: row.allowPublicProjects,
      requireTwoFactor: row.requireTwoFactor,
      digestHourUtc: row.digestHourUtc,
      enabledFlagOverrides: parseJsonArray<string>(row.enabledFlagOverrides),
    },
    createdAt: brandStamp(row.createdAt),
    updatedAt: brandStamp(row.updatedAt),
    archivedAt: brandStampOrNull(row.archivedAt),
  };
}

