/**
 * Personal API tokens. Only a hash of each secret is stored, and no read here
 * ever hands that hash back: rows leave this module as `ApiToken`.
 */
import { and, count, desc, eq, gt, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { apiTokens, getDb } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toApiToken } from "./_mappers";
import type { ApiToken, ApiTokenScope } from "@/types/api-token";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";

export interface NewApiToken {
  readonly orgId: OrgId;
  readonly userId: UserId;
  readonly name: string;
  readonly scope: ApiTokenScope;
  readonly prefix: string;
  readonly tokenHash: string;
  readonly expiresAt: IsoTimestamp;
  /** Also the instant "usable" is judged at when the allowance is counted. */
  readonly createdAt: IsoTimestamp;
}

/**
 * Inserts the token unless the user already holds `limit` usable ones (not
 * revoked, not yet expired) in the organization; `null` means "over the
 * limit, nothing stored". Counting and inserting share one synchronous
 * transaction so two concurrent creations cannot both slip under the limit.
 */
export async function insertApiTokenWithinLimit(
  input: NewApiToken,
  limit: number,
): Promise<ApiToken | null> {
  return getDb().transaction((tx) => {
    const usable = tx
      .select({ value: count() })
      .from(apiTokens)
      .where(
        and(
          orgPredicate(apiTokens.orgId, input.orgId),
          eq(apiTokens.userId, input.userId),
          isNull(apiTokens.revokedAt),
          gt(apiTokens.expiresAt, input.createdAt),
        ),
      )
      .get();

    if ((usable?.value ?? 0) >= limit) return null;

    const row = tx
      .insert(apiTokens)
      .values({
        id: newId(),
        orgId: input.orgId,
        userId: input.userId,
        name: input.name,
        scope: input.scope,
        prefix: input.prefix,
        tokenHash: input.tokenHash,
        expiresAt: input.expiresAt,
        lastUsedAt: null,
        revokedAt: null,
        createdAt: input.createdAt,
      })
      .returning()
      .get();

    return toApiToken(row);
  });
}

export async function findApiTokenById(
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.id, tokenId)))
    .get();
  return row ? toApiToken(row) : null;
}

/**
 * The bearer check runs before any `Actor` exists, so this is a read that is
 * not scoped by `orgId` — the hash is the credential and carries the tenant
 * with it.
 */
export async function findApiTokenByHash(
  tokenHash: string,
): Promise<ApiToken | null> {
  const row = getDb()
    .select()
    .from(apiTokens)
    .where(eq(apiTokens.tokenHash, tokenHash))
    .get();
  return row ? toApiToken(row) : null;
}

/** Every token of one user in one org — revoked and expired included — newest first. */
export async function listApiTokens(
  orgId: OrgId,
  userId: UserId,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .select()
    .from(apiTokens)
    .where(
      and(orgPredicate(apiTokens.orgId, orgId), eq(apiTokens.userId, userId)),
    )
    // `rowid` breaks ties between tokens created in the same millisecond.
    .orderBy(desc(apiTokens.createdAt), sql`rowid desc`)
    .all();

  return rows.map(toApiToken);
}

/**
 * Sets `revokedAt` on a token that is still live. `null` when it was already
 * revoked (or is not in this org), so a caller can tell "I revoked it" from
 * "someone had beaten me to it" and audit only the former.
 */
export async function revokeApiToken(
  orgId: OrgId,
  tokenId: string,
  at: IsoTimestamp,
): Promise<ApiToken | null> {
  const row = getDb()
    .update(apiTokens)
    .set({ revokedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .get();

  return row ? toApiToken(row) : null;
}

/** Revokes every not-yet-revoked token of the user in the org, expired ones included. */
export async function revokeUnrevokedApiTokensForUser(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<readonly ApiToken[]> {
  const rows = getDb()
    .update(apiTokens)
    .set({ revokedAt: at })
    .where(
      and(
        orgPredicate(apiTokens.orgId, orgId),
        eq(apiTokens.userId, userId),
        isNull(apiTokens.revokedAt),
      ),
    )
    .returning()
    .all();

  return rows.map(toApiToken);
}

/**
 * Stamps `lastUsedAt`, but only while the token is still usable at `at`.
 * `false` means it was revoked or expired in the meantime and nothing changed.
 */
export async function touchApiTokenLastUsed(
  tokenId: string,
  at: IsoTimestamp,
): Promise<boolean> {
  const rows = getDb()
    .update(apiTokens)
    .set({ lastUsedAt: at })
    .where(
      and(
        eq(apiTokens.id, tokenId),
        isNull(apiTokens.revokedAt),
        gt(apiTokens.expiresAt, at),
      ),
    )
    .returning({ id: apiTokens.id })
    .all();

  return rows.length > 0;
}

