/**
 * Personal API tokens: minting, listing, revoking and bearer authentication. Only a hash of the secret is ever stored.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, subscribe, hashToken, randomToken, resolveActor
 */
import { emit, subscribe } from "@/lib/event-bus";
import { hashToken, randomToken } from "@/lib/hash";
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { createApiTokenSchema } from "@/schemas/api-token";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { toIsoTimestamp } from "@/types/common";
import { actorEnvelope, envelope, orgResource, requireFound } from "./_support";
import { resolveActor } from "./member-service";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { ApiToken } from "@/types/api-token";
import type { OrgId, UserId } from "@/types/common";
import type { TaskflowEventPayload, Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";

/** Marks a string as a Taskflow API secret; also what `prefix` is cut from. */
const TOKEN_PREFIX = "tfk_";

/** Random bytes behind the secret, before URL-safe encoding. */
const TOKEN_BYTES = 32;

/** How many characters of the secret are kept as the recognisable `prefix`. */
const DISPLAY_PREFIX_LENGTH = 12;

/** Usable (not revoked, not expired) tokens one user may hold per organization. */
const MAX_USABLE_TOKENS = 5;

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * Mints a token. The secret is returned here and nowhere else: the row keeps
 * a hash, so a lost secret cannot be recovered, only replaced.
 */
export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);

  assertOrgScope(actor, parsed.orgId);
  if (parsed.scope === "write") {
    assertCan(actor, "api_token:create_write", orgResource(parsed.orgId));
  }

  const token = `${TOKEN_PREFIX}${randomToken(TOKEN_BYTES)}`;
  const now = new Date();

  const apiToken = await apiTokenRepo.insertApiTokenWithinLimit(
    {
      orgId: parsed.orgId,
      userId: actor.userId,
      name: parsed.name,
      scope: parsed.scope,
      prefix: token.slice(0, DISPLAY_PREFIX_LENGTH),
      tokenHash: hashToken(token),
      expiresAt: toIsoTimestamp(
        new Date(now.getTime() + parsed.expiresInDays * MS_PER_DAY),
      ),
      createdAt: toIsoTimestamp(now),
    },
    MAX_USABLE_TOKENS,
  );

  if (apiToken === null) {
    throw new Error(
      `You can have at most ${MAX_USABLE_TOKENS} active API tokens in this organization; revoke one first`,
    );
  }

  await emit("api_token.created", {
    ...actorEnvelope(actor),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
    expiresAt: apiToken.expiresAt,
  });

  return { token, apiToken };
}

/** A user's tokens in the org, revoked and expired ones included, newest first. */
export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId: UserId = actor.userId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  if (userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }

  return apiTokenRepo.listApiTokens(orgId, userId);
}

/**
 * Revoking is idempotent: a token that is already revoked comes back as it
 * was, with its original `revokedAt`, and nothing more is audited.
 */
export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);

  const existing = requireFound(
    await apiTokenRepo.findApiTokenById(orgId, tokenId),
    "API token",
    tokenId,
  );
  if (existing.userId !== actor.userId) {
    assertCan(actor, "api_token:manage_others", orgResource(orgId));
  }
  if (existing.revokedAt !== null) return existing;

  const revoked = await apiTokenRepo.revokeApiToken(
    orgId,
    tokenId,
    toIsoTimestamp(new Date()),
  );

  if (revoked === null) {
    // A concurrent revocation got there first; that call audits it.
    return requireFound(
      await apiTokenRepo.findApiTokenById(orgId, tokenId),
      "API token",
      tokenId,
    );
  }

  await emit("api_token.revoked", {
    ...actorEnvelope(actor),
    tokenId: revoked.id,
    userId: revoked.userId,
    name: revoked.name,
    scope: revoked.scope,
  });

  return revoked;
}

/**
 * Resolves the `Actor` a bearer secret stands for, or `null`. The role is read
 * at call time, never frozen into the token: a `write` token follows its
 * member's role up and down, while a `read` token is always a viewer.
 */
export async function authenticateApiToken(
  token: string,
): Promise<Actor | null> {
  if (typeof token !== "string" || !token.startsWith(TOKEN_PREFIX)) return null;

  const apiToken = await apiTokenRepo.findApiTokenByHash(hashToken(token));
  if (apiToken === null || apiToken.revokedAt !== null) return null;

  const now = toIsoTimestamp(new Date());
  if (apiToken.expiresAt <= now) return null;

  // `findOrgById` still returns deleted (archived) organizations.
  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (org === null || org.archivedAt !== null) return null;

  const member = await resolveActor(apiToken.userId, apiToken.orgId);
  if (member === null) return null;

  // The guarded update is the last word: it refuses a token that was revoked
  // or expired since the read above, so a failed call never leaves a trace.
  if (!(await apiTokenRepo.touchApiTokenLastUsed(apiToken.id, now))) return null;

  return {
    userId: member.userId,
    orgId: member.orgId,
    role: apiToken.scope === "read" ? "viewer" : member.role,
  };
}

/**
 * Attaches the reactive half of the token lifecycle. Called once from
 * `event-registry`; the returned function detaches it.
 */
export function registerApiTokenListeners(): Unsubscribe {
  return subscribe("member.removed", revokeTokensOfRemovedMember);
}

/**
 * A removed member's tokens must not outlive their membership, expired ones
 * included. Each one revoked here is announced like any other revocation,
 * with the remover as the actor; tokens already revoked are left alone.
 */
async function revokeTokensOfRemovedMember(
  payload: TaskflowEventPayload<"member.removed">,
): Promise<void> {
  const revoked = await apiTokenRepo.revokeUnrevokedApiTokensForUser(
    payload.orgId,
    payload.userId,
    toIsoTimestamp(new Date()),
  );

  for (const apiToken of revoked) {
    await emit("api_token.revoked", {
      ...envelope(payload.orgId, payload.actorId),
      tokenId: apiToken.id,
      userId: apiToken.userId,
      name: apiToken.name,
      scope: apiToken.scope,
    });
  }
}

