/**
 * Personal API tokens: creation limits, listing, revocation, bearer
 * authentication, the removed-member cascade and the audit trail.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
import { ZodError } from "zod";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { activityFilterSchema } from "@/schemas/activity";
import { getDb } from "@/server/db";
import * as apiTokenRepo from "@/server/repositories/api-token-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as activityService from "@/server/services/activity-service";
import * as apiTokenService from "@/server/services/api-token-service";
import { NotFoundError } from "@/server/services/_support";
import {
  registerEventHandlers,
  unregisterEventHandlers,
} from "@/server/services/event-registry";
import * as memberService from "@/server/services/member-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ApiToken } from "@/types/api-token";
import type { ActivityEvent } from "@/types/activity";
import type { CreateApiTokenInput } from "@/schemas/api-token";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

const DAY_MS = 24 * 60 * 60 * 1000;
const START = new Date("2026-06-01T10:00:00.000Z");

let cleanup: () => void;
let counter = 0;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

afterEach(() => {
  vi.useRealTimers();
});

function freshTenant(): Promise<Tenant> {
  counter += 1;
  return createTenant(`api-token-${counter}`, "growth");
}

function input(
  orgId: OrgId,
  overrides: Partial<CreateApiTokenInput> = {},
): CreateApiTokenInput {
  return { orgId, name: "CI", scope: "read", expiresInDays: 30, ...overrides };
}

async function mint(
  actor: Actor,
  overrides: Partial<CreateApiTokenInput> = {},
): Promise<{ token: string; apiToken: ApiToken }> {
  return apiTokenService.createApiToken(actor, input(actor.orgId, overrides));
}

async function auditRows(
  tenant: Tenant,
  subjectKind: "api_token" = "api_token",
): Promise<readonly ActivityEvent[]> {
  const page = await activityService.listActivity(
    tenant.actors.admin,
    activityFilterSchema.parse({ orgId: tenant.org.id, subjectKind, limit: 100 }),
  );
  return page.items;
}

function storedRows(orgId: OrgId) {
  return getDb().$client
    .prepare("SELECT * FROM api_tokens WHERE org_id = ?")
    .all(orgId) as readonly Record<string, unknown>[];
}

describe("createApiToken", () => {
  it("returns the secret once and stores only its hash", async () => {
    const tenant = await freshTenant();
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);

    const { token, apiToken } = await mint(tenant.actors.member, {
      name: "  Deploy script  ",
      scope: "write",
      expiresInDays: 7,
    });

    expect(token).toMatch(/^tfk_[A-Za-z0-9_-]+$/);
    expect(apiToken).toEqual({
      id: expect.any(String),
      orgId: tenant.org.id,
      userId: tenant.userIds.member,
      name: "Deploy script",
      scope: "write",
      prefix: token.slice(0, 12),
      expiresAt: new Date(START.getTime() + 7 * DAY_MS).toISOString(),
      lastUsedAt: null,
      revokedAt: null,
      createdAt: START.toISOString(),
    });
    expect(JSON.stringify(apiToken)).not.toContain(token);
    expect(JSON.stringify(apiToken)).not.toContain(hashToken(token));

    const [row] = storedRows(tenant.org.id);
    expect(row?.token_hash).toBe(hashToken(token));
    expect(JSON.stringify(row)).not.toContain(token);
  });

  it("hands out a different secret every time", async () => {
    const tenant = await freshTenant();
    const a = await mint(tenant.actors.member);
    const b = await mint(tenant.actors.member);
    expect(a.token).not.toBe(b.token);
  });

  it("rejects invalid input with the ZodError and stores nothing", async () => {
    const tenant = await freshTenant();
    const actor = tenant.actors.member;
    const bad: Partial<CreateApiTokenInput>[] = [
      { name: "   " },
      { name: "x".repeat(81) },
      { scope: "admin" as never },
      { expiresInDays: 0 },
      { expiresInDays: 366 },
      { expiresInDays: 1.5 },
    ];

    for (const overrides of bad) {
      await expect(mint(actor, overrides)).rejects.toBeInstanceOf(ZodError);
    }
    await expect(
      apiTokenService.createApiToken(actor, input("not-a-ulid" as OrgId)),
    ).rejects.toBeInstanceOf(ZodError);

    expect(storedRows(tenant.org.id)).toHaveLength(0);
    expect(await auditRows(tenant)).toHaveLength(0);
  });

  it("accepts the boundaries of the name and expiry ranges", async () => {
    const tenant = await freshTenant();
    await mint(tenant.actors.member, { name: "x", expiresInDays: 1 });
    await mint(tenant.actors.member, { name: "y".repeat(80), expiresInDays: 365 });
    expect(storedRows(tenant.org.id)).toHaveLength(2);
  });

  it("refuses another organization's id", async () => {
    const tenant = await freshTenant();
    const other = await freshTenant();

    await expect(
      apiTokenService.createApiToken(tenant.actors.owner, input(other.org.id)),
    ).rejects.toBeInstanceOf(TenantScopeError);
    expect(storedRows(other.org.id)).toHaveLength(0);
  });

  it("lets a viewer hold a read token but not a write token", async () => {
    const tenant = await freshTenant();

    await expect(mint(tenant.actors.viewer, { scope: "read" })).resolves.toBeDefined();
    await expect(
      mint(tenant.actors.viewer, { scope: "write" }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(mint(tenant.actors.member, { scope: "write" })).resolves.toBeDefined();
    await expect(mint(tenant.actors.admin, { scope: "write" })).resolves.toBeDefined();
    await expect(mint(tenant.actors.owner, { scope: "write" })).resolves.toBeDefined();
    expect(storedRows(tenant.org.id)).toHaveLength(4);
  });

  it("caps a user at five usable tokens per organization", async () => {
    const tenant = await freshTenant();
    const actor = tenant.actors.member;
    const minted: ApiToken[] = [];
    for (let i = 0; i < 5; i += 1) {
      minted.push((await mint(actor, { name: `t${i}` })).apiToken);
    }

    await expect(mint(actor)).rejects.toThrow();
    expect(storedRows(tenant.org.id)).toHaveLength(5);
    expect(await auditRows(tenant)).toHaveLength(5);

    // Other users have their own allowance.
    await expect(mint(tenant.actors.admin)).resolves.toBeDefined();

    // A revoked token frees a slot.
    await apiTokenService.revokeApiToken(actor, tenant.org.id, minted[0]!.id);
    await expect(mint(actor)).resolves.toBeDefined();
    await expect(mint(actor)).rejects.toThrow();
  });

  it("does not count expired tokens against the cap", async () => {
    const tenant = await freshTenant();
    const actor = tenant.actors.member;
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);

    for (let i = 0; i < 4; i += 1) await mint(actor, { expiresInDays: 1 });
    await mint(actor, { expiresInDays: 10 });
    await expect(mint(actor)).rejects.toThrow();

    // Exactly at the four short tokens' expiry they stop counting.
    vi.setSystemTime(new Date(START.getTime() + DAY_MS));
    for (let i = 0; i < 4; i += 1) await mint(actor, { expiresInDays: 10 });
    await expect(mint(actor)).rejects.toThrow();
  });

  it("counts the cap per organization", async () => {
    const tenant = await freshTenant();
    const other = await freshTenant();
    await memberRepo.insertMember(other.org.id, tenant.userIds.member, "member", null);
    const home = tenant.actors.member;
    const away: Actor = { ...home, orgId: other.org.id };

    for (let i = 0; i < 5; i += 1) await mint(home);
    await expect(mint(away)).resolves.toBeDefined();
  });

  it("never lets concurrent creations exceed the cap", async () => {
    const tenant = await freshTenant();
    const results = await Promise.allSettled(
      Array.from({ length: 8 }, () => mint(tenant.actors.member)),
    );
    expect(results.filter((r) => r.status === "fulfilled")).toHaveLength(5);
    expect(storedRows(tenant.org.id)).toHaveLength(5);
  });
});

describe("listApiTokens", () => {
  it("lists the actor's own tokens, revoked and expired included, newest first", async () => {
    const tenant = await freshTenant();
    const actor = tenant.actors.member;
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);

    const first = (await mint(actor, { name: "first", expiresInDays: 1 })).apiToken;
    const second = (await mint(actor, { name: "second" })).apiToken;
    const third = (await mint(actor, { name: "third" })).apiToken;
    await mint(tenant.actors.admin, { name: "someone else's" });
    await apiTokenService.revokeApiToken(actor, tenant.org.id, second.id);
    vi.setSystemTime(new Date(START.getTime() + 2 * DAY_MS));

    const listed = await apiTokenService.listApiTokens(actor, tenant.org.id);

    expect(listed.map((t) => t.id)).toEqual([third.id, second.id, first.id]);
    expect(listed[1]?.revokedAt).toEqual(expect.any(String));
  });

  it("orders newest first across different creation times", async () => {
    const tenant = await freshTenant();
    const actor = tenant.actors.member;
    vi.useFakeTimers({ toFake: ["Date"] });

    const ids: string[] = [];
    for (let i = 0; i < 3; i += 1) {
      vi.setSystemTime(new Date(START.getTime() + i * 1000));
      ids.push((await mint(actor)).apiToken.id);
    }

    const listed = await apiTokenService.listApiTokens(actor, tenant.org.id);
    expect(listed.map((t) => t.id)).toEqual([...ids].reverse());
  });

  it("lets only admins and owners list another user's tokens", async () => {
    const tenant = await freshTenant();
    const { apiToken } = await mint(tenant.actors.member);
    const target = tenant.userIds.member;

    for (const role of ["admin", "owner"] as const) {
      const listed = await apiTokenService.listApiTokens(
        tenant.actors[role],
        tenant.org.id,
        target,
      );
      expect(listed.map((t) => t.id)).toEqual([apiToken.id]);
    }
    for (const role of ["member", "viewer"] as const) {
      await expect(
        apiTokenService.listApiTokens(tenant.actors[role], tenant.org.id, target),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
    }
    // Naming yourself explicitly is not "someone else".
    await expect(
      apiTokenService.listApiTokens(tenant.actors.member, tenant.org.id, target),
    ).resolves.toHaveLength(1);
  });

  it("refuses another organization's id", async () => {
    const tenant = await freshTenant();
    const other = await freshTenant();
    await expect(
      apiTokenService.listApiTokens(tenant.actors.owner, other.org.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("revokeApiToken", () => {
  it("revokes the actor's own token and audits it", async () => {
    const tenant = await freshTenant();
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);
    const { apiToken } = await mint(tenant.actors.member);

    vi.setSystemTime(new Date(START.getTime() + 5000));
    const revoked = await apiTokenService.revokeApiToken(
      tenant.actors.member,
      tenant.org.id,
      apiToken.id,
    );

    expect(revoked).toEqual({
      ...apiToken,
      revokedAt: new Date(START.getTime() + 5000).toISOString(),
    });
    const rows = (await auditRows(tenant)).filter((r) => r.action === "api_token.revoked");
    expect(rows).toHaveLength(1);
    expect(rows[0]).toMatchObject({
      actorId: tenant.userIds.member,
      subjectKind: "api_token",
      subjectId: apiToken.id,
    });
  });

  it("is idempotent: the original revokedAt survives and nothing more is audited", async () => {
    const tenant = await freshTenant();
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);
    const { apiToken } = await mint(tenant.actors.member);

    vi.setSystemTime(new Date(START.getTime() + 1000));
    const first = await apiTokenService.revokeApiToken(tenant.actors.member, tenant.org.id, apiToken.id);
    vi.setSystemTime(new Date(START.getTime() + 9000));
    const again = await apiTokenService.revokeApiToken(tenant.actors.member, tenant.org.id, apiToken.id);
    const byAdmin = await apiTokenService.revokeApiToken(tenant.actors.admin, tenant.org.id, apiToken.id);

    expect(again).toEqual(first);
    expect(byAdmin).toEqual(first);
    const rows = (await auditRows(tenant)).filter((r) => r.action === "api_token.revoked");
    expect(rows).toHaveLength(1);
  });

  it("audits a concurrent double revoke only once", async () => {
    const tenant = await freshTenant();
    const { apiToken } = await mint(tenant.actors.member);

    await Promise.all([
      apiTokenService.revokeApiToken(tenant.actors.member, tenant.org.id, apiToken.id),
      apiTokenService.revokeApiToken(tenant.actors.admin, tenant.org.id, apiToken.id),
    ]);

    const rows = (await auditRows(tenant)).filter((r) => r.action === "api_token.revoked");
    expect(rows).toHaveLength(1);
  });

  it("lets admins and owners, but not peers, revoke someone else's token", async () => {
    const tenant = await freshTenant();

    for (const role of ["member", "viewer"] as const) {
      const { apiToken } = await mint(tenant.actors.admin);
      await expect(
        apiTokenService.revokeApiToken(tenant.actors[role], tenant.org.id, apiToken.id),
      ).rejects.toBeInstanceOf(PermissionDeniedError);
      const stored = await apiTokenRepo.findApiTokenById(tenant.org.id, apiToken.id);
      expect(stored?.revokedAt).toBeNull();
      await apiTokenService.revokeApiToken(tenant.actors.owner, tenant.org.id, apiToken.id);
    }

    const { apiToken } = await mint(tenant.actors.member);
    const revoked = await apiTokenService.revokeApiToken(tenant.actors.admin, tenant.org.id, apiToken.id);
    expect(revoked.revokedAt).not.toBeNull();
    const rows = (await auditRows(tenant)).filter(
      (r) => r.action === "api_token.revoked" && r.subjectId === apiToken.id,
    );
    expect(rows[0]?.actorId).toBe(tenant.userIds.admin);
  });

  it("reports unknown ids and other organizations' tokens", async () => {
    const tenant = await freshTenant();
    const other = await freshTenant();
    const { apiToken } = await mint(other.actors.member);

    await expect(
      apiTokenService.revokeApiToken(tenant.actors.owner, tenant.org.id, "01HZZZNOPENOPENOPENOPENOPE"),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      apiTokenService.revokeApiToken(tenant.actors.owner, tenant.org.id, apiToken.id),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      apiTokenService.revokeApiToken(tenant.actors.owner, other.org.id, apiToken.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });
});

describe("authenticateApiToken", () => {
  it("resolves the actor and stamps lastUsedAt", async () => {
    const tenant = await freshTenant();
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);
    const { token, apiToken } = await mint(tenant.actors.admin, { scope: "write" });

    vi.setSystemTime(new Date(START.getTime() + 60_000));
    const actor = await apiTokenService.authenticateApiToken(token);

    expect(actor).toEqual({
      userId: tenant.userIds.admin,
      orgId: tenant.org.id,
      role: "admin",
    });
    const [stored] = await apiTokenService.listApiTokens(tenant.actors.admin, tenant.org.id);
    expect(stored?.id).toBe(apiToken.id);
    expect(stored?.lastUsedAt).toBe(new Date(START.getTime() + 60_000).toISOString());
  });

  it("gives a read token the viewer role whatever the member's role", async () => {
    const tenant = await freshTenant();
    const { token } = await mint(tenant.actors.owner, { scope: "read" });
    expect((await apiTokenService.authenticateApiToken(token))?.role).toBe("viewer");
  });

  it("gives a write token the member's role at the time of the call", async () => {
    const tenant = await freshTenant();
    const { token } = await mint(tenant.actors.member, { scope: "write" });
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);

    expect((await apiTokenService.authenticateApiToken(token))?.role).toBe("member");
    await memberRepo.updateMemberRole(tenant.org.id, member!.id, "admin");
    expect((await apiTokenService.authenticateApiToken(token))?.role).toBe("admin");
    await memberRepo.updateMemberRole(tenant.org.id, member!.id, "viewer");
    expect((await apiTokenService.authenticateApiToken(token))?.role).toBe("viewer");
  });

  it("rejects unknown secrets", async () => {
    await freshTenant();
    expect(await apiTokenService.authenticateApiToken("")).toBeNull();
    expect(await apiTokenService.authenticateApiToken("tfk_nope")).toBeNull();
    expect(await apiTokenService.authenticateApiToken("not-a-token")).toBeNull();
  });

  it("rejects revoked tokens without touching them", async () => {
    const tenant = await freshTenant();
    const { token, apiToken } = await mint(tenant.actors.member);
    await apiTokenService.revokeApiToken(tenant.actors.member, tenant.org.id, apiToken.id);

    expect(await apiTokenService.authenticateApiToken(token)).toBeNull();
    const stored = await apiTokenRepo.findApiTokenById(tenant.org.id, apiToken.id);
    expect(stored?.lastUsedAt).toBeNull();
  });

  it("stops working at exactly expiresAt", async () => {
    const tenant = await freshTenant();
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);
    const { token, apiToken } = await mint(tenant.actors.member, { expiresInDays: 2 });
    const expiry = new Date(apiToken.expiresAt).getTime();

    vi.setSystemTime(new Date(expiry - 1));
    expect(await apiTokenService.authenticateApiToken(token)).not.toBeNull();

    vi.setSystemTime(new Date(expiry));
    expect(await apiTokenService.authenticateApiToken(token)).toBeNull();

    const stored = await apiTokenRepo.findApiTokenById(tenant.org.id, apiToken.id);
    expect(stored?.lastUsedAt).toBe(new Date(expiry - 1).toISOString());
  });

  it("rejects tokens of removed members and leaves lastUsedAt alone", async () => {
    const tenant = await freshTenant();
    const { token, apiToken } = await mint(tenant.actors.member);
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    await memberRepo.archiveMember(tenant.org.id, member!.id);

    expect(await apiTokenService.authenticateApiToken(token)).toBeNull();
    const stored = await apiTokenRepo.findApiTokenById(tenant.org.id, apiToken.id);
    expect(stored?.lastUsedAt).toBeNull();
  });

  it("rejects tokens of suspended members", async () => {
    const tenant = await freshTenant();
    const { token } = await mint(tenant.actors.member);
    getDb().$client
      .prepare("UPDATE members SET status = 'suspended' WHERE org_id = ? AND user_id = ?")
      .run(tenant.org.id, tenant.userIds.member);

    expect(await apiTokenService.authenticateApiToken(token)).toBeNull();
  });

  it("rejects tokens of a deleted organization", async () => {
    const tenant = await freshTenant();
    const { token, apiToken } = await mint(tenant.actors.owner);
    await orgRepo.archiveOrg(tenant.org.id);

    expect(await apiTokenService.authenticateApiToken(token)).toBeNull();
    const stored = await apiTokenRepo.findApiTokenById(tenant.org.id, apiToken.id);
    expect(stored?.lastUsedAt).toBeNull();
  });
});

describe("member removal", () => {
  it("revokes every unrevoked token of the removed member and audits the remover", async () => {
    const tenant = await freshTenant();
    const other = await freshTenant();
    await memberRepo.insertMember(other.org.id, tenant.userIds.viewer, "viewer", null);
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);

    const viewer = tenant.actors.viewer;
    const alreadyRevoked = (await mint(viewer, { name: "old" })).apiToken;
    const expired = (await mint(viewer, { name: "expired", expiresInDays: 1 })).apiToken;
    const live = (await mint(viewer, { name: "live" })).apiToken;
    const elsewhere = (
      await mint({ ...viewer, orgId: other.org.id }, { name: "elsewhere" })
    ).apiToken;
    const bystander = (await mint(tenant.actors.member)).apiToken;

    vi.setSystemTime(new Date(START.getTime() + 1000));
    const originalRevocation = await apiTokenService.revokeApiToken(viewer, tenant.org.id, alreadyRevoked.id);
    vi.setSystemTime(new Date(START.getTime() + 2 * DAY_MS));

    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    await memberService.removeMember(tenant.actors.admin, {
      orgId: tenant.org.id,
      memberId: target!.id,
    });

    const byId = (list: readonly ApiToken[], id: string) => list.find((t) => t.id === id);
    const removedTokens = await apiTokenRepo.listApiTokens(tenant.org.id, tenant.userIds.viewer);
    const removedAt = new Date(START.getTime() + 2 * DAY_MS).toISOString();
    expect(byId(removedTokens, live.id)?.revokedAt).toBe(removedAt);
    expect(byId(removedTokens, expired.id)?.revokedAt).toBe(removedAt);
    expect(byId(removedTokens, alreadyRevoked.id)?.revokedAt).toBe(originalRevocation.revokedAt);

    const elsewhereStored = await apiTokenRepo.findApiTokenById(other.org.id, elsewhere.id);
    expect(elsewhereStored?.revokedAt).toBeNull();
    const bystanderStored = await apiTokenRepo.findApiTokenById(tenant.org.id, bystander.id);
    expect(bystanderStored?.revokedAt).toBeNull();

    const revocations = (await auditRows(tenant)).filter((r) => r.action === "api_token.revoked");
    expect(revocations.map((r) => r.subjectId).sort()).toEqual(
      [alreadyRevoked.id, expired.id, live.id].sort(),
    );
    const cascade = revocations.filter((r) => r.subjectId !== alreadyRevoked.id);
    expect(cascade).toHaveLength(2);
    for (const row of cascade) expect(row.actorId).toBe(tenant.userIds.admin);
  });
});

describe("audit log", () => {
  it("records creation and revocation, and never the secret or its hash", async () => {
    const tenant = await freshTenant();
    const { token, apiToken } = await mint(tenant.actors.member, { name: "Nightly" });
    await apiTokenService.revokeApiToken(tenant.actors.member, tenant.org.id, apiToken.id);

    const rows = await auditRows(tenant);
    expect(rows.map((r) => r.action).sort()).toEqual(["api_token.created", "api_token.revoked"]);
    for (const row of rows) {
      expect(row).toMatchObject({
        orgId: tenant.org.id,
        actorId: tenant.userIds.member,
        subjectKind: "api_token",
        subjectId: apiToken.id,
      });
    }

    const serialized = JSON.stringify(rows);
    expect(serialized).not.toContain(token);
    expect(serialized).not.toContain(token.slice(4));
    expect(serialized).not.toContain(token.slice(0, 12));
    expect(serialized).not.toContain(hashToken(token));
  });

  it("accepts the new action and subject kind in audit-log filters", () => {
    const parsed = activityFilterSchema.parse({
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      action: ["api_token.created", "api_token.revoked"],
      subjectKind: "api_token",
    });
    expect(parsed.action).toEqual(["api_token.created", "api_token.revoked"]);
    expect(parsed.subjectKind).toBe("api_token");
  });
});

